begin;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email) values ('cf100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','intent-replay@example.test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"cf100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2}')::text,true);
create temp table ids(label text primary key,id uuid);
insert into ids values('a',public.create_wallet('Original receiver','cash','USD',10000)),('b',public.create_wallet('Target','cash','USD',0));
insert into ids select 'a-usd',default_balance_id from public.wallets where id=(select id from ids where label='a');
insert into ids select 'b-usd',default_balance_id from public.wallets where id=(select id from ids where label='b');
insert into ids select 'a-lbp',id from public.wallet_balances where wallet_id=(select id from ids where label='a') and currency='LBP';
create temp table transfer_result as select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000011','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='b-usd'),100,100,'Move intent');
select results_eq($q$select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000011','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='b-usd'),100,100,'Move intent')$q$,$q$select * from transfer_result$q$,'exact Move replay returns original transaction and revision');
select is((select count(*) from public.transactions where note='Move intent'),1::bigint,'exact Move retry records exactly one event');
select throws_ok($q$select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000011','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='b-usd'),101,101,'Move intent')$q$,'BT003','transaction conflict','changed Move payload under same token conflicts');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2,"LBP":0}')::text,true);
create temp table exchange_result as select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000012','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='a-lbp'),100,90000,'Exchange intent',90000);
select results_eq($q$select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000012','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='a-lbp'),100,90000,'Exchange intent',90000)$q$,$q$select * from exchange_result$q$,'exact Exchange replay retains original transaction/revision');
select is((select count(*) from public.transactions where note='Exchange intent'),1::bigint,'exact Exchange retry records exactly one event');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":3,"LBP":0}')::text,true);
select throws_ok($q$select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000012','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='a-lbp'),100,90000,'Exchange intent',90000)$q$,'BT003','transaction conflict','units participate in exact retry identity');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2}')::text,true);
select lives_ok($q$select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000013','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='b-usd'),100,100,'Move intent')$q$,'a distinct legitimate intent can have identical amounts');
select is((select count(*) from public.transactions where note='Move intent'),2::bigint,'distinct tokens preserve two genuine transfers');
select ok(not has_function_privilege('authenticated','public.record_transfer(date,uuid,uuid,bigint,bigint,text,integer)','execute'),'legacy transfer without intent is not publicly executable');
select ok(not has_function_privilege('authenticated','public.record_balance_transfer(date,uuid,uuid,bigint,bigint,text,integer)','execute'),'legacy balance transfer without intent is not publicly executable');
-- Full signed deletion preview. Re-read never substitutes a fresh amount.
create function pg_temp.plan_for(p_wallet uuid) returns jsonb language sql as $$
 select jsonb_agg(jsonb_build_object('balanceId',b.id,'counterpartBalanceId',case when t.balance_minor<>0 then dest.id else null end,'expectedAmountMinor',t.balance_minor,'expectedUnit',jsonb_build_object('code',c.code,'decimalPlaces',c.decimal_places)) order by b.id)
 from public.wallet_balances b join public.wallet_balance_totals t on t.balance_id=b.id join public.currencies c on(c.user_id,c.code)=(b.user_id,b.currency)
 join public.wallet_balances dest on dest.wallet_id=(select id from ids where label='b') and dest.currency=b.currency where b.wallet_id=p_wallet;
$$;
create temp table confirmation as select pg_temp.plan_for((select id from ids where label='a')) payload;
insert into public.transactions(kind,occurred_on,balance_id,currency,amount_minor,category_id) select 'expense','2026-11-05',(select id from ids where label='a-usd'),'USD',20000,id from public.categories where kind='expense' and parent_id is null order by position limit 1;
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'P0001','wallet.deletionConflict','opposite signed amount cannot reverse confirmed settlement');
select is((select count(*) from public.transactions where note='Wallet settlement'),0::bigint,'conflicted complete plan produces no partial legs');
select ok((select deleted_at is null from public.wallets where id=(select id from ids where label='a')),'conflict leaves source active');
update confirmation set payload=pg_temp.plan_for((select id from ids where label='a'));
insert into public.transactions(kind,occurred_on,balance_id,currency,amount_minor,category_id) select 'expense','2026-11-05',(select id from ids where label='a-usd'),'USD',1,id from public.categories where kind='expense' and parent_id is null order by position limit 1;
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'P0001','wallet.deletionConflict','same-sign changed magnitude requires fresh confirmation');
update confirmation set payload=pg_temp.plan_for((select id from ids where label='a'));
select set_config('request.headers',jsonb_build_object('x-budget-units','{"SYP":0}')::text,true);
insert into public.transactions(kind,occurred_on,balance_id,currency,amount_minor,category_id) select 'income','2026-11-05',b.id,'SYP',1,c.id from public.wallet_balances b cross join public.categories c where b.wallet_id=(select id from ids where label='a') and b.currency='SYP' and c.kind='income' and c.parent_id is null order by c.position limit 1;
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'P0001','wallet.deletionConflict','zero-to-nonzero transition invalidates the full plan');
update confirmation set payload=pg_temp.plan_for((select id from ids where label='a'));
insert into public.transactions(kind,occurred_on,balance_id,currency,amount_minor,category_id) select 'expense','2026-11-05',b.id,'SYP',1,c.id from public.wallet_balances b cross join public.categories c where b.wallet_id=(select id from ids where label='a') and b.currency='SYP' and c.kind='expense' and c.parent_id is null order by c.position limit 1;
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'P0001','wallet.deletionConflict','nonzero-to-zero transition invalidates confirmed settlement');
update confirmation set payload=pg_temp.plan_for((select id from ids where label='a'));
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2}')::text,true);
update public.profiles set salary_balance_id=(select id from ids where label='a-usd'),salary_amount_minor=100 where user_id=auth.uid();
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'P0001','wallet.deletionConflict','new saved dependency invalidates the confirmation before any legs');
update public.profiles set salary_balance_id=null,salary_amount_minor=null where user_id=auth.uid();
select public.create_currency('NEWZERO','N',2);
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'P0001','wallet.deletionConflict','new zero currency balance invalidates the complete balance set');
update confirmation set payload=pg_temp.plan_for((select id from ids where label='a'));
select lives_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'fresh complete signed plan settles and tombstones');
select is((select sum(abs(balance_minor)) from public.wallet_balance_totals where wallet_id=(select id from ids where label='a')),0::numeric,'all balances settle exactly');
select lives_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),(select payload from confirmation))$q$,'successful deletion receipt replays before tombstone restrictions');
select throws_ok($q$select public.settle_and_delete_wallet('cf100000-0000-4000-8000-000000000020',(select id from ids where label='a'),jsonb_set((select payload from confirmation),'{0,expectedAmountMinor}','123'))$q$,'P0001','wallet.deletionConflict','successful deletion token rejects changed signed snapshot');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2}')::text,true);
select results_eq($q$select * from public.record_balance_transfer('cf100000-0000-4000-8000-000000000011','2026-11-05',(select id from ids where label='a-usd'),(select id from ids where label='b-usd'),100,100,'Move intent')$q$,$q$select * from transfer_result$q$,'successful transfer receipt survives source tombstone and returns original revision');
set constraints all immediate;
select * from finish();
rollback;
